-- ==============================================================================================
-- BASELINE, PART 2 — the foreign keys of the tables the history never created.
--
-- Generated by scripts/gen_baseline_migration.mjs. Do not hand-edit; re-run the generator.
--
-- These are separated from the baseline itself and dated to run LAST, and the reason is a
-- failure rather than a preference. With the FKs at the end of the baseline, a real fresh
-- database died at statement 134: public.company_goals references org_departments, which is
-- created by 20260724020640_org_foundation — a migration that runs AFTER the baseline. A
-- foreign key can only be added once BOTH tables exist, and for these tables that moment is
-- not the start of the history but the end of it.
--
-- Each is guarded on the constraint's absence, so production and staging — which have every
-- one of them already — are untouched.
-- ==============================================================================================

do $$ begin
  if not exists (select 1 from pg_constraint where conname='agent_actions_decision_log_id_fkey'
                 and conrelid='public.agent_actions'::regclass) then
    alter table public.agent_actions add constraint agent_actions_decision_log_id_fkey FOREIGN KEY (decision_log_id) REFERENCES decision_log(id);
  end if;
end $$;
do $$ begin
  if not exists (select 1 from pg_constraint where conname='catalog_subcategories_domain_slug_fkey'
                 and conrelid='public.catalog_subcategories'::regclass) then
    alter table public.catalog_subcategories add constraint catalog_subcategories_domain_slug_fkey FOREIGN KEY (domain_slug) REFERENCES catalog_domains(slug) ON DELETE CASCADE;
  end if;
end $$;
